{
  "openapi": "3.0.3",
  "info": {
    "title": "Freya Bank statement and debt services",
    "version": "2026-10-01",
    "description": "The seven business services called by the Turkish-language phone assistant, with later business decisions through 10 October 2026. Tool request schemas expose only the fields inside the bank request's data object."
  },
  "servers": [
    {
      "url": "https://freya-bank-mock.mehar-144.workers.dev/voice/v1"
    }
  ],
  "paths": {
    "/cards.list": {
      "post": {
        "operationId": "cards_list",
        "summary": "Retrieve the caller's cards at the start of the flow, before selecting a card or reading its debt.",
        "requestBody": {
          "required": true,
          "content": {
            "application/json": {
              "schema": {
                "type": "object",
                "properties": {
                  "customerNo": {
                    "type": "string",
                    "description": "The 8-digit customer number from call variable customerNumber; never ask the caller for it. The bank also accepts a number."
                  },
                  "aiFlow": {
                    "type": "string",
                    "description": "The fixed use-case identifier sent by the integration; ignored in test.",
                    "enum": [
                      "CardOps"
                    ]
                  }
                },
                "required": [
                  "customerNo",
                  "aiFlow"
                ]
              }
            }
          }
        },
        "responses": {
          "200": {
            "description": "Cards retrieved; success requires result.returnCode = \"1\".",
            "content": {
              "application/json": {
                "schema": {
                  "type": "object",
                  "properties": {
                    "data": {
                      "type": "object",
                      "properties": {
                        "cards": {
                          "type": "array",
                          "description": "The caller's active cards. Select only from this list; last four digits and product names need not be unique.",
                          "items": {
                            "type": "object",
                            "properties": {
                              "cardNumber": {
                                "type": "string",
                                "description": "Preserve this value exactly for subsequent requests. Masked first-six/last-four in test; full number in production per 9 October decision. Never speak more than the last four digits."
                              },
